    },
    'Transferrin_Saturation': {
        'normal_range': (20, 50),  # %
        'no_conversion': True
    },
    'Ferritin': {
        'normal_range': (24, 336),  # ng/mL
        'alt_unit': {'factor': 2.247, 'name': 'pmol/L', 'description': 'convert from pmol/L to ng/mL by dividing by 2.247'},
        'upper_outlier_threshold': 1000.0
    },
    'Reticulocyte_Count': {
        'normal_range': (0.5, 2.5),  # %
        'no_conversion': True
    },

    # Liver Function
    'Total_Bilirubin': {
        'normal_range': (0.1, 1.2),  # mg/dL
        'alt_unit': {'factor': 17.1, 'name': 'µmol/L', 'description': 'convert from µmol/L to mg/dL by dividing by 17.1'},
        'upper_outlier_threshold': 5.0
    },
    'Direct_Bilirubin': {
        'normal_range': (0.0, 0.3),  # mg/dL
        'alt_unit': {'factor': 17.1, 'name': 'µmol/L'},
        'upper_outlier_threshold': 2.0
    },
    'Albumin_Serum': {
        'normal_range': (3.5, 5.5),  # g/dL
        'alt_unit': {'factor': 10.0, 'name': 'g/L', 'description': 'convert from g/L to g/dL by dividing by 10'},
        'upper_outlier_threshold': 8.0
    },
    'Total_Protein': {
        'normal_range': (6.0, 8.3),  # g/dL
        'alt_unit': {'factor': 10.0, 'name': 'g/L'},
        'upper_outlier_threshold': 12.0
    },
    'Prealbumin': {
        'normal_range': (20, 40),  # mg/dL
        'alt_unit': {'factor': 10.0, 'name': 'g/L'},
        'upper_outlier_threshold': 100.0
    },
    'CRP': {
        'normal_range': (0.0, 10.0),  # mg/L
        'alt_unit': {'factor': 10.0, 'name': 'g/L'},
        'upper_outlier_threshold': 100.0
    },

    # Lipids
    'Total_Cholesterol': {
        'normal_range': (125, 200),  # mg/dL
        'alt_unit': {'factor': 0.02586, 'name': 'mmol/L', 'description': 'convert from mmol/L to mg/dL by multiplying by 38.67'},
        'upper_outlier_threshold': 400.0
    },
    'LDL_Cholesterol': {
        'normal_range': (0, 100),  # mg/dL (optimal <100)
        'alt_unit': {'factor': 0.02586, 'name': 'mmol/L'},
        'upper_outlier_threshold': 300.0
    },
    'HDL_Cholesterol': {
        'normal_range': (40, 100),  # mg/dL (>60 is protective)
        'alt_unit': {'factor': 0.02586, 'name': 'mmol/L'},
        'upper_outlier_threshold': 200.0
    },
    'Triglycerides': {
        'normal_range': (0, 150),  # mg/dL
        'alt_unit': {'factor': 0.01129, 'name': 'mmol/L', 'description': 'convert from mmol/L to mg/dL by multiplying by 88.6'},
