    },
    'Non_HDL_Cholesterol': {
        'normal_range': (0, 130),  # mg/dL
        'alt_unit': {'factor': 0.02586, 'name': 'mmol/L'},
        'upper_outlier_threshold': 300.0
    },

    # Glucose & Glycemic Control
    'Glucose': {
        'normal_range': (70, 100),  # mg/dL (fasting)
        'alt_unit': {'factor': 0.05551, 'name': 'mmol/L', 'description': 'convert from mmol/L to mg/dL by multiplying by 18.02'},
        'upper_outlier_threshold': 300.0
    },
    'HbA1c': {
        'normal_range': (4.0, 6.0),  # % (or mmol/mol)
        'note': 'Usually always in %, but may be in mmol/mol if >20 (divide by 10.93)',
        'upper_outlier_threshold': 15.0
    },
    'Fructosamine': {
        'normal_range': (200, 285),  # µmol/L
        'alt_unit': {'factor': 0.03333, 'name': 'mg/dL', 'description': 'convert from mg/dL to µmol/L by multiplying by 30'},
        'upper_outlier_threshold': 400.0
    },

    # Uric Acid
    'Uric_Acid': {
        'normal_range': (3.5, 7.2),  # mg/dL
        'alt_unit': {'factor': 59.48, 'name': 'µmol/L', 'description': 'convert from µmol/L to mg/dL by dividing by 59.48'},
        'upper_outlier_threshold': 15.0
    },

    # Urine Tests
    'Urine_Albumin': {
        'normal_range': (0, 30),  # mg/L (or mg/24hr, commonly <30)
        'alt_unit': {'factor': 1.0, 'name': 'varies'},
        'upper_outlier_threshold': 300.0
    },
    'Urine_Creatinine': {
        'normal_range': (50, 250),  # mg/dL (varies widely)
        'alt_unit': {'factor': 8.84, 'name': 'mmol/L', 'description': 'convert from mmol/L to mg/dL by multiplying by 8.84'},
