    },
    'Albumin_to_Creatinine_Ratio_Urine': {
        'normal_range': (0, 30),  # mg/g (or <3 mg/mmol)
        'alt_unit': {'factor': 0.1131, 'name': 'mg/mmol', 'description': 'convert from mg/mmol to mg/g by multiplying by 8.84'},
