    'Protein_to_Creatinine_Ratio_Urine': {
        'normal_range': (0, 200),  # mg/g (nephrotic if >3500 mg/day)
        'alt_unit': {'factor': 0.1131, 'name': 'mg/mmol'},
        'upper_outlier_threshold': 10000.0
    },
    'Urine_Protein': {
        'normal_range': (0, 150),  # mg/L or mg/24hr
        'alt_unit': {'factor': 10.0, 'name': 'g/L'},
        'upper_outlier_threshold': 1000.0
    },
    'Urine_pH': {
        'normal_range': (4.5, 8.0),  # pH units
        'no_conversion': True
    },
