        'normal_range': (1.005, 1.030),  # no units
        'no_conversion': True
    },

    # Cardiac Markers
    'BNP': {
        'normal_range': (0, 100),  # pg/mL
        'alt_unit': {'factor': 1.0, 'name': 'pmol/L'},
