        'upper_outlier_threshold': 5.0
    },
    'Free_T3': {
        'normal_range': (2.0, 4.4),  # pg/mL
        'alt_unit': {'factor': 1.536, 'name': 'pmol/L', 'description': 'convert from pmol/L to pg/mL by dividing by 1.536'},
        'upper_outlier_threshold': 20.0
    },

    # Blood Gas
    'pH_Arterial': {
        'normal_range': (7.35, 7.45),  # pH units
        'no_conversion': True
    },
