def parse_value(val):
    """Parse a value that may contain commas as decimals or scientific notation."""
    if pd.isna(val) or val == '' or val is None:
        return np.nan

    val = str(val).strip()

    # Handle empty strings
    if not val:
        return np.nan

    try:
        # Replace comma with dot for decimal separator
        val = val.replace(',', '.')

        # Convert to float (handles scientific notation automatically)
        return float(val)
    except (ValueError, TypeError):
        return np.nan

def normalize_decimal(value, decimal_places=2):
    """Format a numeric value to X.XX format."""
    if pd.isna(value):
        return np.nan
    try:
        return float(f"{float(value):.{decimal_places}f}")
    except:
        return np.nan

def convert_unit_if_needed(feature, value, ranges_dict):
    """
    Detect if value is likely in alternative units and convert to standard US units.
    Returns the converted value if conversion was needed, otherwise returns original.
    """
    if pd.isna(value):
        return np.nan

    if feature not in ranges_dict:
        return value

    feature_info = ranges_dict[feature]

    # Skip features that don't need conversion
    if feature_info.get('no_conversion', False):
        return value

    # Get normal range
    normal_range = feature_info.get('normal_range')
    if not normal_range:
        return value

    min_val, max_val = normal_range

    # Check if value is within normal range
    if min_val <= value <= max_val:
        return value

    # Check if there's an alternative unit
    alt_unit = feature_info.get('alt_unit')
    if not alt_unit:
        return value

    conversion_factor = alt_unit.get('factor', 1.0)

    # Convert and check if result falls in normal range
    converted_value = value * conversion_factor

    if min_val <= converted_value <= max_val:
        return converted_value

    # If still outside range, check upper outlier threshold
    upper_threshold = feature_info.get('upper_outlier_threshold', max_val * 10)
    if value > upper_threshold:
        # Try conversion
        if min_val <= converted_value <= max_val:
            return converted_value

    return value

def main():
    print("Loading clinical lab data...")
    df = pd.read_csv('/root/environment/data/ckd_lab_data.csv')

    print(f"Initial shape: {df.shape}")
    print(f"Columns: {df.columns.tolist()}")

    # Step 1: Remove rows with missing values
    print("\n=== STEP 1: Removing incomplete records ===")
    initial_rows = len(df)
    df = df.dropna(how='any')
    final_rows = len(df)
    print(f"Rows removed: {initial_rows - final_rows}")
    print(f"Remaining rows: {final_rows}")

    # Step 2 & 3 & 4: Parse values, handle scientific notation, decimal formats, and unit conversion
    print("\n=== STEP 2-4: Converting values and handling unit conversions ===")

    # Exclude patient_id from processing
    numeric_columns = [col for col in df.columns if col != 'patient_id']

    for col in numeric_columns:
        print(f"Processing {col}...", end=" ")

        # Parse all values
        parsed = df[col].apply(parse_value)

        # Apply unit conversion if needed
        converted = parsed.apply(lambda x: convert_unit_if_needed(col, x, PHYSIO_RANGES))

        # Normalize to 2 decimal places
        normalized = converted.apply(lambda x: normalize_decimal(x, 2))

        df[col] = normalized
        print(f"Done")

    # Format output - ensure all numeric values are in X.XX format
    print("\n=== STEP 5: Formatting output ===")

    output_df = df.copy()

    # Format numeric columns to X.XX format
    for col in numeric_columns:
        output_df[col] = output_df[col].apply(
            lambda x: f"{x:.2f}" if pd.notna(x) else ""
        )

    # Save to output file
    output_path = '/root/ckd_lab_data_harmonized.csv'
    output_df.to_csv(output_path, index=False)

    print(f"\nHarmonized data saved to: {output_path}")
    print(f"Output shape: {output_df.shape}")

    # Validation
    print("\n=== Validation ===")
    print(f"Total rows: {len(output_df)}")
    print(f"Total columns: {len(output_df.columns)}")
    print(f"Expected columns: {len(df.columns)}")

    # Check for scientific notation, commas, inconsistent decimals in output
    print("\nChecking for data format issues in output:")
    issues_found = False
    for col in numeric_columns:
        for idx, val in enumerate(output_df[col]):
            if pd.isna(val) or val == "":
                continue
            val_str = str(val)
            if 'e' in val_str.lower() or ',' in val_str:
                print(f"  Issue in {col} row {idx}: {val}")
                issues_found = True
            # Check decimal places
            if '.' in val_str:
                decimal_part = val_str.split('.')[1]
                if len(decimal_part) != 2:
                    print(f"  Decimal issue in {col} row {idx}: {val} (expected 2 decimals)")
                    issues_found = True

    if not issues_found:
        print("  ✓ No format issues detected!")

    # Show sample output
    print("\n=== Sample Output (first 5 rows) ===")
    print(output_df.iloc[:5, :8])

if __name__ == "__main__":
    main()

